mkfn!{
    check_pointers_introspect!();
    #[doc = " Utility for adding a check for read/write on every sized, raw pointer."] #[doc = ""] #[doc = " Visits every read/write access to a [Sized], raw pointer and inserts a"] #[doc = " new basic block directly before the pointer access. (Read/write accesses"] #[doc = " are determined by the `PlaceContext` of the MIR visitor.) Then calls"] #[doc = " `on_finding` to insert the actual logic for a pointer check (e.g. check for"] #[doc = " alignment). A check can choose to follow borrows of field projections via"] #[doc = " the `field_projection_mode` parameter."] #[doc = ""] #[doc = " This utility takes care of the right order of blocks, the only thing a"] #[doc = " caller must do in `on_finding` is:"] #[doc = " - Append [Statement]s to `stmts`."] #[doc = " - Append [LocalDecl]s to `local_decls`."] #[doc = " - Return a [PointerCheck] that contains the condition and an [AssertKind]."] #[doc = "   The AssertKind must be a panic with `#[rustc_nounwind]`. The condition"] #[doc = "   should always return the boolean `is_ok`, so evaluate to true in case of"] #[doc = "   success and fail the check otherwise."] #[doc = " This utility will insert a terminator block that asserts on the condition"] #[doc = " and panics on failure."] pub (crate) fn check_pointers < 'tcx , F > (tcx : TyCtxt < 'tcx > , body : & mut Body < 'tcx > , excluded_pointees : & [Ty < 'tcx >] , on_finding : F , field_projection_mode : BorrowedFieldProjectionMode ,) where F : Fn (TyCtxt < 'tcx > , Place < 'tcx > , Ty < 'tcx > , PlaceContext , & mut IndexVec < Local , LocalDecl < 'tcx > > , & mut Vec < Statement < 'tcx > > , SourceInfo ,) -> PointerCheck < 'tcx > , { if tcx . lang_items () . get (LangItem :: PanicImpl) . is_none () { return ; } let typing_env = body . typing_env (tcx) ; let basic_blocks = body . basic_blocks . as_mut () ; let local_decls = & mut body . local_decls ; for block in basic_blocks . indices () . rev () { for statement_index in (0 .. basic_blocks [block] . statements . len ()) . rev () { let location = Location { block , statement_index } ; let statement = & basic_blocks [block] . statements [statement_index] ; let source_info = statement . source_info ; let mut finder = PointerFinder :: new (tcx , local_decls , typing_env , excluded_pointees , field_projection_mode ,) ; finder . visit_statement (statement , location) ; for (local , ty , context) in finder . into_found_pointers () { debug ! ("Inserting check for {:?}" , ty) ; let new_block = split_block (basic_blocks , location) ; let block_data = & mut basic_blocks [block] ; let pointer_check = on_finding (tcx , local , ty , context , local_decls , & mut block_data . statements , source_info ,) ; block_data . terminator = Some (Terminator { source_info , kind : TerminatorKind :: Assert { cond : pointer_check . cond , expected : true , target : new_block , msg : pointer_check . assert_kind , unwind : UnwindAction :: Unreachable , } , }) ; } } } }
}
